declare doc jsonb;
begin
 select state into doc from td_settlement_validation_test;
 assert doc#>>'{tournaments,0,status}'='completed','Completion was not retained';
 assert doc#>>'{tournaments,0,endedBy}'='icm-chop','ICM ending was not retained';
 assert jsonb_array_length(doc#>'{tournaments,0,icmChop,participants}')=2,'Participant records were not retained';
 assert (doc#>>'{tournaments,0,entries,0,finalChipCount}')::bigint=60000,'Final chip count changed';
 assert (doc#>>'{tournaments,0,settlement,houseContribution}')::bigint=68000,'Guarantee funding changed';
 assert (select sum(value::bigint) from jsonb_array_elements_text(doc#>'{tournaments,0,finalPayouts}'))=(doc#>>'{tournaments,0,settlement,pool}')::bigint,'Payouts no longer match funding';
 assert (select count(*) from jsonb_array_elements(doc#>'{tournaments,0,entries}') e where e->>'eliminatedAt' is not null)=8,'Earlier eliminations changed';
 assert not exists(select 1 from jsonb_array_elements(doc#>'{tournaments,0,entries}') e where e ? 'points'),'Points were unexpectedly assigned';
 update td_settlement_validation_test set state=jsonb_set(state,'{players,0,name}','"Renamed Settlement Player"'::jsonb);
 assert (select state#>>'{tournaments,0,icmChop,participants,0,playerId}' from td_settlement_validation_test)='settlement-player-1','Rename changed the payout identity';
end $$;
select 'PASS: funded ICM settlements and permanent player links survive storage validation' as result;
rollback;
